type LocaleFoundation = Readonly<{
  current: string; planned: string; roadmap: string;
  wahooLive: string; garminPlanned: string; wearableRoadmap: string;
  guideTitle: (source: string, target: string) => string;
  guideIntro: (source: string, target: string) => string;
  guideSummary: (source: string, target: string) => string;
  dataTitle: string; dataIntro: string;
  dataPoints: readonly string[]; prompts: readonly string[]; faqs: readonly Faq[];
}>;

function makeProviderGuides(f: LocaleFoundation): Record<ProviderGuideSlug, ProviderGuideContent> {
  const build = (slug: ProviderGuideSlug, source: string, target: string, mode: "current" | "planned" | "roadmap"): ProviderGuideContent => {
    const statusLabel = mode === "current" ? f.current : mode === "planned" ? f.planned : f.roadmap;
    const status = mode === "current" ? f.wahooLive : mode === "planned" ? f.garminPlanned : f.wearableRoadmap;
    const noIndex = mode === "planned";
    return {
      metaTitle: f.guideTitle(source, target),
      metaDescription: f.guideIntro(source, target),
      eyebrow: `${source} · ${target}`,
      title: f.guideTitle(source, target),
      intro: f.guideIntro(source, target),
      summary: f.guideSummary(source, target),
      statusLabel,
      status,
      dataTitle: f.dataTitle,
      dataIntro: f.dataIntro,
      dataPoints: f.dataPoints,
      prompts: f.prompts,
      faqs: f.faqs,
      noIndex,
    };
  };
  return {
    "wahoo-to-chatgpt": build("wahoo-to-chatgpt", "Wahoo", "ChatGPT", "current"),
    "wahoo-to-claude": build("wahoo-to-claude", "Wahoo", "Claude", "current"),
    "wahoo-mcp": build("wahoo-mcp", "Wahoo", "MCP", "current"),
    "garmin-to-chatgpt": build("garmin-to-chatgpt", "Garmin", "ChatGPT", "planned"),
    "garmin-to-claude": build("garmin-to-claude", "Garmin", "Claude", "planned"),
    "garmin-mcp": build("garmin-mcp", "Garmin", "MCP", "planned"),
    "wearable-mcp": build("wearable-mcp", "Wearables", "MCP", "roadmap"),
  };
}

