Object.assign(idPublic, { legal: {
  updated: "Terakhir diperbarui: 16 Agustus 2026",
  privacy: { metaTitle: "Kebijakan Privasi", metaDescription: "Cara TRAPEAK menangani data akun, latihan, nutrisi, berat, profil, laboratorium, dan akses berbagi.", eyebrow: "LEGAL / 01", title: "Kebijakan Privasi", intro: "Kebijakan ini menjelaskan cara TRAPEAK menangani data pribadi melalui trapeak.com dan layanan beta terbatas. Identitas operator serta yurisdiksi akan diterbitkan sebelum peluncuran umum.", sections: [
    { title: "1. Data yang kami kumpulkan", paragraphs: ["Kami memproses identitas akun dan keamanan, data kebugaran yang diizinkan, serta catatan yang Anda minta untuk disimpan: latihan, nutrisi, berat bertanggal, konteks profil, kondisi, obat, dan hasil laboratorium. Undangan akses, kategori, masa berlaku, dan peristiwa audit juga diproses."] },
    { title: "2. Cara data digunakan", paragraphs: ["Data digunakan untuk autentikasi, pengoperasian dan keamanan layanan, sinkronisasi sumber, penyimpanan catatan yang diminta, serta penyediaan data kepada AI atau orang yang Anda izinkan. TRAPEAK tidak mendiagnosis kondisi medis."] },
    { title: "3. Koneksi dan berbagi", paragraphs: ["Menghubungkan sumber atau AI memerlukan tindakan Anda. Kami tidak menjual data pribadi. Anda dapat memberi akses hanya-baca sementara untuk Latihan, Nutrisi, atau Kesehatan melalui email dan mencabutnya kapan saja."] },
    { title: "4. Penyimpanan, keamanan, dan hak", paragraphs: ["Kredensial penyedia dienkripsi dan payload mentah tidak ditampilkan melalui MCP. Bergantung pada lokasi, Anda dapat meminta akses, koreksi, ekspor, atau penghapusan data."] },
    { title: "5. Pemrosesan internasional dan kontak", paragraphs: ["Penyedia dapat memproses data di negara lain dengan perlindungan yang berlaku. Layanan ini tidak ditujukan bagi anak di bawah 16 tahun. Hubungi support@trapeak.com."] },
  ] },
  terms: { metaTitle: "Ketentuan Layanan", metaDescription: "Ketentuan beta privat, koneksi AI, dan akses yang didelegasikan.", eyebrow: "LEGAL / 02", title: "Ketentuan Layanan", intro: "Ketentuan ini berlaku untuk trapeak.com dan layanan beta terbatas. Detail operator, hukum yang berlaku, dan syarat akun publik akan diterbitkan sebelum peluncuran umum.", sections: [
    { title: "1. Tujuan layanan", paragraphs: ["TRAPEAK adalah lapisan data yang dikendalikan pengguna antara sumber yang didukung, catatan yang disimpan atas permintaan, AI kompatibel, dan orang yang diizinkan. Fitur beta dapat berubah."] },
    { title: "2. Keluaran AI dan nasihat medis", paragraphs: ["TRAPEAK meneruskan data yang diizinkan dan tidak membuat diagnosis, terapi, atau nasihat profesional. Keluaran AI pihak ketiga dapat tidak lengkap atau keliru; tinjau keputusan penting secara mandiri."] },
    { title: "3. Integrasi dan akses", paragraphs: ["Ketersediaan bergantung pada kesiapan teknis dan persetujuan penyedia. Akses delegasi bersifat sementara, hanya-baca, dan terbatas per kategori."] },
    { title: "4. Penggunaan yang wajar dan hak kekayaan", paragraphs: ["Anda tidak boleh mengakses data orang lain, mengganggu layanan, memasukkan kode berbahaya, atau melanggar hukum. Nama, desain, dan konten asli TRAPEAK dilindungi."] },
    { title: "5. Ketersediaan dan kontak", paragraphs: ["Layanan beta disediakan sebagaimana adanya dan dapat berubah atau dihentikan. Pertanyaan dapat dikirim ke support@trapeak.com."] },
  ] },
  deletion: { metaTitle: "Penghapusan Data", metaDescription: "Cara menghapus catatan, memutus sumber, mencabut akses, atau meminta penghapusan akun.", eyebrow: "LEGAL / 03", title: "Penghapusan Data", intro: "Anda mengendalikan catatan di TRAPEAK. Catatan yang didukung dapat dihapus dari dasbor atau melalui permintaan AI yang eksplisit; akses delegasi dapat dicabut segera.", sections: [
    { title: "Hapus catatan tertentu", paragraphs: ["Gunakan Hapus di dasbor atau minta AI secara eksplisit menghapus makanan atau laporan tertentu. Menghapus laporan juga menghapus hasilnya dan tidak dapat dibatalkan."] },
    { title: "Minta penghapusan penuh", paragraphs: ["Putuskan Wahoo, lalu kirim email dari alamat akun Anda ke support@trapeak.com dengan subjek “Data deletion request”. Jangan kirim kata sandi, token, atau detail kesehatan."] },
    { title: "Yang terjadi selanjutnya", paragraphs: ["Kami dapat meminta verifikasi identitas terbatas. Data yang memenuhi syarat biasanya dihapus atau dianonimkan dalam 30 hari; sebagian catatan dapat disimpan untuk keamanan atau kewajiban hukum."] },
    { title: "Layanan terhubung", paragraphs: ["Memutus sumber tidak otomatis menghapus data yang sudah disimpan. Menghapus data TRAPEAK tidak menghapus informasi yang disimpan Wahoo, AI, atau layanan lain secara terpisah."] },
  ] },
} });

